export async function getServerSideProps({ res }) {
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.end("<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>L&D Th\u1ef1c Chi\u1ebfn \u00b7 PeopleOS by TaHien</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=Be+Vietnam+Pro:wght@300;400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --navy:#020B18;--navy2:#062040;--navy3:#0A2E50;\n  --cyan:#22D3EE;--teal:#06B6D4;--gold:#F0C040;--gold3:#d97706;\n  --green:#22c55e;--red:#ef4444;--emerald:#10b981;--em2:#059669;\n  --text:#F0F6FF;--muted:#94A3B8;--subtle:#4A7A94;\n  --glass:rgba(255,255,255,0.04);--glass2:rgba(255,255,255,0.07);\n  --border:rgba(16,185,129,0.15);--border2:rgba(16,185,129,0.30);\n  --r:14px;--r-sm:9px;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{font-size:16px;scroll-behavior:smooth}\nbody{font-family:'Be Vietnam Pro',sans-serif;background:var(--navy);color:var(--text);line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:0;\n  background:radial-gradient(ellipse 80% 50% at 5% 0%,rgba(16,185,129,.08) 0%,transparent 55%),\n             radial-gradient(ellipse 60% 40% at 95% 100%,rgba(240,192,64,.06) 0%,transparent 55%)}\nbody::after{content:'\u5b78';position:fixed;right:-40px;top:50%;transform:translateY(-50%) rotate(-6deg);\n  font-size:300px;line-height:1;color:rgba(16,185,129,.025);pointer-events:none;z-index:0;\n  font-family:'Playfair Display',serif}\n.app{position:relative;z-index:1;max-width:780px;margin:0 auto;padding:0 20px 100px}\n.topnav{display:flex;align-items:center;justify-content:space-between;padding:18px 0 14px;border-bottom:1px solid var(--border);margin-bottom:28px}\n.back{display:flex;align-items:center;gap:7px;font-size:13px;color:var(--muted);text-decoration:none;transition:color .18s}\n.back:hover{color:var(--emerald)}\n.logo{display:flex;align-items:center;gap:9px}\n.lmark{width:30px;height:30px;border-radius:8px;background:linear-gradient(135deg,var(--em2),var(--navy3));display:flex;align-items:center;justify-content:center;font-family:'Playfair Display',serif;font-size:13px;color:var(--emerald);border:1px solid var(--border2)}\n.lname{font-size:13px;font-weight:600;color:var(--cyan)}.lsub{font-size:10px;color:var(--muted)}\n.prog-wrap{margin-bottom:24px}\n.prog-meta{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:7px}\n.prog-bar{height:3px;background:rgba(255,255,255,.07);border-radius:2px;overflow:hidden}\n.prog-fill{height:100%;border-radius:2px;background:linear-gradient(90deg,var(--em2),var(--emerald));transition:width .55s cubic-bezier(.4,0,.2,1)}\n.dots{display:flex;gap:7px;justify-content:center;margin-bottom:28px}\n.dot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.1);cursor:pointer;transition:all .22s;border:1.5px solid transparent;flex-shrink:0}\n.dot.active{background:var(--emerald);border-color:var(--emerald);transform:scale(1.4)}\n.dot.done{background:var(--em2);border-color:var(--em2)}\n/* HERO */\n.hero{position:relative;border-radius:var(--r);overflow:hidden;margin-bottom:24px;height:190px;border:1px solid rgba(16,185,129,.2)}\n.hero-bg{position:absolute;inset:0}\n.hero-grad{position:absolute;inset:0;background:linear-gradient(135deg,#051a10 0%,#080f20 50%,#020B18 100%)}\n.hero-pattern{position:absolute;inset:0;opacity:.13;\n  background-image:linear-gradient(rgba(16,185,129,.4) 1px,transparent 1px),linear-gradient(90deg,rgba(16,185,129,.4) 1px,transparent 1px);\n  background-size:28px 28px}\n.hero-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(2,11,24,.95) 0%,rgba(2,11,24,.2) 65%,transparent 100%)}\n.hero-content{position:absolute;bottom:18px;left:22px;right:22px}\n.hero-badge{display:inline-flex;align-items:center;gap:5px;background:rgba(16,185,129,.13);border:1px solid var(--border2);border-radius:20px;padding:3px 11px;font-size:11px;color:var(--emerald);margin-bottom:9px;font-weight:500;letter-spacing:.05em}\n.hero-badge::before{content:'';width:5px;height:5px;border-radius:50%;background:var(--emerald)}\n.hero-num{font-size:12px;color:var(--muted);margin-bottom:4px}\n.hero-title{font-family:'Playfair Display',serif;font-size:22px;font-weight:800;color:#fff;line-height:1.25}\n.mv{display:none}.mv.active{display:block;animation:fadeUp .38s ease}\n@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}\n/* CONTENT */\n.lead{border-left:2.5px solid var(--emerald);padding:13px 17px;background:rgba(16,185,129,.05);border-radius:0 var(--r-sm) var(--r-sm) 0;font-style:italic;color:var(--text);font-size:14.5px;line-height:1.7;margin-bottom:22px}\n.body{font-size:14.5px;line-height:1.78;color:var(--text);margin-bottom:15px}\n.body b{color:var(--emerald);font-weight:600}\n.sec-title{font-size:10.5px;letter-spacing:.13em;color:var(--em2);font-weight:600;text-transform:uppercase;margin:22px 0 11px}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:18px}\n@media(max-width:480px){.grid2{grid-template-columns:1fr}}\n.card{background:var(--glass);border:1px solid rgba(255,255,255,.07);border-radius:var(--r-sm);padding:13px 15px}\n.cn{font-size:10px;color:var(--gold);font-weight:700;margin-bottom:5px;letter-spacing:.07em}\n.ct{font-size:13.5px;font-weight:600;color:var(--text);margin-bottom:4px}\n.cd{font-size:12.5px;color:var(--muted);line-height:1.5}\n.card-full{background:var(--glass);border:1px solid rgba(255,255,255,.07);border-radius:var(--r-sm);padding:14px 16px;margin-bottom:10px}\n.hl{background:rgba(16,185,129,.06);border:1px solid rgba(16,185,129,.22);border-radius:var(--r-sm);padding:14px 17px;margin-bottom:18px}\n.hl-label{font-size:10.5px;color:var(--emerald);font-weight:700;letter-spacing:.08em;margin-bottom:7px}\n.hl p{font-size:13.5px;color:var(--text);line-height:1.6}\n.ins{background:rgba(240,192,64,.06);border:1px solid rgba(240,192,64,.2);border-radius:var(--r-sm);padding:13px 17px;margin-bottom:18px}\n.ins-label{font-size:10.5px;color:var(--gold);font-weight:700;letter-spacing:.08em;margin-bottom:6px}\n.ins p{font-size:13px;color:var(--text);line-height:1.55}\n.warn{background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.2);border-radius:var(--r-sm);padding:13px 17px;margin-bottom:18px}\n.warn-label{font-size:10.5px;color:var(--red);font-weight:700;letter-spacing:.08em;margin-bottom:6px}\n.warn p{font-size:13px;color:var(--text);line-height:1.55}\n/* EXERCISE */\n.ex{background:var(--glass2);border:1px solid var(--border2);border-radius:var(--r);padding:18px;margin-top:22px}\n.ex-head{display:flex;align-items:center;gap:10px;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid var(--border)}\n.ex-ico{width:30px;height:30px;border-radius:8px;flex-shrink:0;background:rgba(16,185,129,.12);border:1px solid rgba(16,185,129,.25);display:flex;align-items:center;justify-content:center;font-size:14px}\n.ex-label{font-size:12.5px;font-weight:700;color:var(--gold)}\n.ex-sub{font-size:11px;color:var(--muted)}\n/* QUIZ */\n.qq{font-size:14px;color:var(--text);margin-bottom:13px;line-height:1.58;font-weight:500}\n.qopts{display:flex;flex-direction:column;gap:7px}\n.qopt{padding:11px 14px;border-radius:var(--r-sm);border:1px solid rgba(255,255,255,.08);background:var(--glass);cursor:pointer;font-size:13.5px;color:var(--text);transition:all .18s;text-align:left;width:100%;display:flex;align-items:flex-start;gap:9px;font-family:'Be Vietnam Pro',sans-serif;line-height:1.5}\n.qopt:hover:not(:disabled){border-color:var(--emerald);background:rgba(16,185,129,.07)}\n.qopt.correct{border-color:#22c55e!important;background:rgba(34,197,94,.09)!important;color:#86efac!important}\n.qopt.wrong{border-color:#ef4444!important;background:rgba(239,68,68,.09)!important;color:#fca5a5!important}\n.oletter{width:22px;height:22px;border-radius:50%;border:1px solid rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-size:10.5px;color:var(--muted);flex-shrink:0;font-weight:700;margin-top:1px}\n.qfb{margin-top:11px;padding:11px 13px;border-radius:var(--r-sm);font-size:13px;line-height:1.5;display:none}\n.qfb.show{display:block}\n.qfb.correct{background:rgba(34,197,94,.09);border:1px solid rgba(34,197,94,.27);color:#86efac}\n.qfb.wrong{background:rgba(239,68,68,.07);border:1px solid rgba(239,68,68,.2);color:#fca5a5}\n/* TNA MATRIX */\n.tna-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}\n.tna-cell{background:var(--glass);border:1px solid rgba(255,255,255,.08);border-radius:var(--r-sm);padding:11px 13px;cursor:pointer;transition:all .2s;font-family:'Be Vietnam Pro',sans-serif}\n.tna-cell:hover:not(.selected){border-color:var(--emerald);background:rgba(16,185,129,.06)}\n.tna-cell.selected{border-color:var(--emerald)!important;background:rgba(16,185,129,.1)!important}\n.tna-cell.correct{border-color:#22c55e!important;background:rgba(34,197,94,.09)!important}\n.tna-cell.incorrect{border-color:#ef4444!important;background:rgba(239,68,68,.07)!important}\n.tna-label{font-size:11px;color:var(--emerald);font-weight:700;margin-bottom:5px;letter-spacing:.06em}\n.tna-text{font-size:13px;color:var(--text);line-height:1.5}\n/* FORMAT SELECTOR */\n.fmt-opts{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.fmt-card{padding:12px 14px;border-radius:var(--r-sm);border:1px solid rgba(255,255,255,.08);background:var(--glass);cursor:pointer;transition:all .2s;font-family:'Be Vietnam Pro',sans-serif}\n.fmt-card:hover:not(:disabled){border-color:var(--emerald);background:rgba(16,185,129,.06)}\n.fmt-card.sel-good{border-color:var(--green)!important;background:rgba(34,197,94,.08)!important}\n.fmt-card.sel-bad{border-color:var(--red)!important;background:rgba(239,68,68,.07)!important}\n.fmt-title{font-size:13px;font-weight:600;color:var(--text);margin-bottom:3px}\n.fmt-desc{font-size:11.5px;color:var(--muted);line-height:1.45}\n/* KIRKPATRICK CALC */\n.kp-levels{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}\n.kp-level{display:grid;grid-template-columns:120px 1fr 80px;gap:10px;align-items:center;padding:10px 12px;border-radius:var(--r-sm);background:var(--glass);border:1px solid rgba(255,255,255,.07)}\n.kp-name{font-size:12px;font-weight:600;color:var(--text)}\n.kp-bar-wrap{height:8px;background:rgba(255,255,255,.07);border-radius:4px;overflow:hidden}\n.kp-bar{height:100%;border-radius:4px;transition:width .5s}\n.kp-pct{font-size:12px;color:var(--muted);text-align:right}\n/* REFLECT */\n.rinput{width:100%;background:rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.08);border-radius:var(--r-sm);padding:11px 13px;color:var(--text);font-family:'Be Vietnam Pro',sans-serif;font-size:13.5px;resize:vertical;min-height:78px;transition:border .18s;line-height:1.6}\n.rinput:focus{outline:none;border-color:var(--emerald)}\n.rinput::placeholder{color:var(--subtle)}\n.chint{font-size:11px;color:var(--subtle);margin-top:5px;text-align:right;transition:color .2s}\n/* CHECKLIST */\n.chi{display:flex;align-items:flex-start;gap:11px;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.05);cursor:pointer}\n.chi:last-child{border-bottom:none}\n.chbox{width:19px;height:19px;border-radius:5px;border:1.5px solid var(--border2);flex-shrink:0;display:flex;align-items:center;justify-content:center;transition:all .18s;margin-top:1px}\n.chbox.on{background:var(--emerald);border-color:var(--emerald)}\n.chbox.on::after{content:'\u2713';font-size:11px;color:#fff;font-weight:800}\n.chtext{font-size:13.5px;color:var(--text);line-height:1.5}\n.chtext small{display:block;font-size:11.5px;color:var(--muted);margin-top:2px}\n/* TAKEAWAY */\n.tw{background:linear-gradient(135deg,rgba(16,185,129,.08),rgba(240,192,64,.05));border:1px solid rgba(16,185,129,.25);border-radius:var(--r);padding:18px 20px;margin-top:22px}\n.tw-label{font-size:10px;letter-spacing:.15em;color:var(--gold);font-weight:700;text-transform:uppercase;margin-bottom:9px}\n.tw-text{font-family:'Playfair Display',serif;font-size:16px;color:var(--text);line-height:1.65;font-style:italic}\n.tw-sig{font-size:11.5px;color:var(--muted);margin-top:9px}\n/* NAV */\n.navbtns{display:flex;align-items:center;justify-content:space-between;margin-top:28px;padding-top:18px;border-top:1px solid var(--border)}\n.btnprev{padding:10px 18px;border-radius:var(--r-sm);border:1px solid rgba(255,255,255,.08);background:transparent;color:var(--muted);font-family:'Be Vietnam Pro',sans-serif;font-size:13.5px;cursor:pointer;transition:all .18s}\n.btnprev:hover:not(:disabled){border-color:rgba(255,255,255,.15);color:var(--text)}\n.btnprev:disabled{opacity:.3;cursor:not-allowed}\n.btnnext{padding:11px 26px;border-radius:var(--r-sm);background:linear-gradient(135deg,var(--em2),var(--emerald));color:#fff;font-family:'Be Vietnam Pro',sans-serif;font-size:13.5px;font-weight:700;cursor:pointer;border:none;transition:all .2s;box-shadow:0 3px 14px rgba(16,185,129,.25)}\n.btnnext:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 5px 18px rgba(16,185,129,.35)}\n.btnnext:disabled{opacity:.28;cursor:not-allowed;transform:none;box-shadow:none;background:var(--subtle);color:var(--navy)}\n.ulock{font-size:11.5px;color:var(--subtle);text-align:center;margin-top:7px}\n/* COMPLETE */\n.cscreen{text-align:center;padding:36px 16px;display:none}\n.cscreen.show{display:block;animation:fadeUp .45s ease}\n.cico{font-size:56px;margin-bottom:18px}\n.ctitle{font-family:'Playfair Display',serif;font-size:26px;color:var(--text);margin-bottom:11px}\n.csub{font-size:14px;color:var(--muted);line-height:1.65;margin-bottom:24px}\n.certcard{background:var(--glass2);border:1px solid rgba(16,185,129,.28);border-radius:var(--r);padding:22px;margin-bottom:22px;position:relative;overflow:hidden}\n.certcard::before{content:'\u5b78';position:absolute;right:-15px;top:50%;transform:translateY(-50%);font-family:'Playfair Display',serif;font-size:90px;color:rgba(16,185,129,.05);pointer-events:none}\n.cert-lbl{font-size:11px;color:var(--emerald);letter-spacing:.12em;font-weight:700;margin-bottom:7px}\n.cert-name{font-family:'Playfair Display',serif;font-size:20px;color:var(--text);margin-bottom:5px}\n.cert-course{font-size:13px;color:var(--muted);margin-bottom:14px}\n.cert-sig{font-size:11.5px;color:var(--subtle);border-top:1px solid var(--border);padding-top:11px;line-height:1.6}\n.btncert{width:100%;padding:13px;border-radius:var(--r-sm);background:linear-gradient(135deg,var(--gold3),var(--gold));color:var(--navy);font-family:'Be Vietnam Pro',sans-serif;font-size:14px;font-weight:700;cursor:pointer;border:none;margin-bottom:9px}\n.btnnext2{width:100%;padding:11px;border-radius:var(--r-sm);background:transparent;border:1px solid rgba(16,185,129,.3);color:var(--emerald);font-family:'Be Vietnam Pro',sans-serif;font-size:13.5px;cursor:pointer;transition:background .18s}\n.btnnext2:hover{background:rgba(16,185,129,.07)}\n/* PHASE COMPLETE BANNER */\n.phase-banner{background:linear-gradient(135deg,rgba(16,185,129,.12),rgba(240,192,64,.08));border:1px solid rgba(16,185,129,.35);border-radius:var(--r);padding:20px 22px;margin-bottom:22px;text-align:center}\n.phase-banner-title{font-family:'Playfair Display',serif;font-size:18px;color:var(--text);margin-bottom:6px}\n.phase-banner-sub{font-size:13px;color:var(--muted);line-height:1.6}\n</style>\n</head>\n<body>\n<div class=\"app\">\n<nav class=\"topnav\">\n  <a class=\"back\" href=\"/\">\u2190 V\u1ec1 Learning Hub</a>\n  <div class=\"logo\"><div class=\"lmark\">\u5b78</div><div><div class=\"lname\">PeopleOS</div><div class=\"lsub\">by TaHien</div></div></div>\n</nav>\n<div class=\"prog-wrap\">\n  <div class=\"prog-meta\"><span id=\"plabel\">B\u00e0i 1 / 6</span><span id=\"ppct\">0%</span></div>\n  <div class=\"prog-bar\"><div class=\"prog-fill\" id=\"pfill\" style=\"width:0%\"></div></div>\n</div>\n<div class=\"dots\" id=\"dots\"></div>\n\n<!-- \u2550\u2550\u2550 M1 \u2014 TNA \u2550\u2550\u2550 -->\n<div class=\"mv active\" id=\"m1\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 1 / 6</div>\n      <div class=\"hero-title\">TNA \u2014 ph\u00e2n t\u00edch nhu c\u1ea7u \u0111\u00e0o t\u1ea1o \u0111\u00fang c\u00e1ch</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"M\u1ed7i n\u0103m m\u1ed9t c\u00f4ng ty trong chu\u1ed7i c\u1ee7a Hi\u1ec1n chi 800 tri\u1ec7u cho training. Sau 3 n\u0103m, Hi\u1ec1n y\u00eau c\u1ea7u team ph\u00e2n t\u00edch xem training n\u00e0o th\u1eadt s\u1ef1 t\u1ea1o ra thay \u0111\u1ed5i h\u00e0nh vi. K\u1ebft qu\u1ea3: 60% ng\u00e2n s\u00e1ch \u0111\u1ed5 v\u00e0o c\u00e1c ch\u01b0\u01a1ng tr\u00ecnh kh\u00f4ng ai nh\u1edb sau 2 tu\u1ea7n. Nguy\u00ean nh\u00e2n: training \u0111\u01b0\u1ee3c ch\u1ecdn d\u1ef1a tr\u00ean 'manager ngh\u0129 nh\u00e2n vi\u00ean c\u1ea7n g\u00ec' \u2014 kh\u00f4ng ph\u1ea3i 'd\u1eef li\u1ec7u cho th\u1ea5y gap l\u00e0 g\u00ec.'\"</div>\n\n  <p class=\"body\">TNA \u2014 Training Needs Analysis \u2014 kh\u00f4ng ph\u1ea3i kh\u1ea3o s\u00e1t h\u1ecfi nh\u00e2n vi\u00ean \"b\u1ea1n mu\u1ed1n h\u1ecdc g\u00ec.\" \u0110\u00f3 l\u00e0 qu\u00e1 tr\u00ecnh <b>x\u00e1c \u0111\u1ecbnh gap gi\u1eefa performance hi\u1ec7n t\u1ea1i v\u00e0 performance k\u1ef3 v\u1ecdng</b>, r\u1ed3i t\u00ecm xem training c\u00f3 ph\u1ea3i gi\u1ea3i ph\u00e1p \u0111\u00fang kh\u00f4ng.</p>\n\n  <div class=\"sec-title\">3 c\u00e2u h\u1ecfi TNA th\u1ef1c chi\u1ebfn \u2014 tr\u01b0\u1edbc khi thi\u1ebft k\u1ebf b\u1ea5t k\u1ef3 ch\u01b0\u01a1ng tr\u00ecnh n\u00e0o</div>\n  <div class=\"card-full\" style=\"border-color:rgba(16,185,129,.25)\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">C\u00e2u h\u1ecfi 1 \u00b7 V\u1ea5n \u0111\u1ec1 th\u1eadt s\u1ef1 l\u00e0 g\u00ec?</div>\n    <div class=\"ct\">\"Nh\u00e2n vi\u00ean thi\u1ebfu k\u1ef9 n\u0103ng\" hay \"quy tr\u00ecnh sai\" hay \"thi\u1ebfu \u0111\u1ed9ng l\u1ef1c\"?</div>\n    <div class=\"cd\" style=\"margin-top:6px\">Training ch\u1ec9 fix \u0111\u01b0\u1ee3c kho\u1ea3ng c\u00e1ch v\u1ec1 ki\u1ebfn th\u1ee9c v\u00e0 k\u1ef9 n\u0103ng \u2014 kh\u00f4ng fix \u0111\u01b0\u1ee3c v\u1ea5n \u0111\u1ec1 v\u1ec1 motivation, quy tr\u00ecnh, hay c\u00f4ng c\u1ee5 thi\u1ebfu. H\u1ecfi: \"N\u1ebfu s\u00fang k\u1ec1 c\u1ed5, h\u1ecd c\u00f3 l\u00e0m \u0111\u01b0\u1ee3c kh\u00f4ng?\" N\u1ebfu c\u00f3 \u2014 v\u1ea5n \u0111\u1ec1 kh\u00f4ng ph\u1ea3i k\u1ef9 n\u0103ng, \u0111\u1eebng training.</div>\n  </div>\n  <div class=\"card-full\" style=\"border-color:rgba(16,185,129,.25)\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">C\u00e2u h\u1ecfi 2 \u00b7 Thay \u0111\u1ed5i h\u00e0nh vi n\u00e0o c\u1ee5 th\u1ec3 c\u1ea7n x\u1ea3y ra?</div>\n    <div class=\"ct\">Kh\u00f4ng ph\u1ea3i \"nh\u00e2n vi\u00ean hi\u1ec3u s\u00e2u h\u01a1n v\u1ec1 customer service\" \u2014 m\u00e0 l\u00e0 g\u00ec c\u1ee5 th\u1ec3?</div>\n    <div class=\"cd\" style=\"margin-top:6px\">\"Sau training, nh\u00e2n vi\u00ean s\u1ebd x\u1eed l\u00fd complaint t\u1eeb kh\u00e1ch h\u00e0ng trong d\u01b0\u1edbi 5 ph\u00fat m\u00e0 kh\u00f4ng c\u1ea7n escalate l\u00ean manager, trong 90% tr\u01b0\u1eddng h\u1ee3p.\" \u2014 \u0110\u00e2y m\u1edbi l\u00e0 behavioral outcome \u0111o \u0111\u01b0\u1ee3c. Kh\u00f4ng c\u00f3 behavioral outcome = kh\u00f4ng bi\u1ebft training c\u00f3 th\u00e0nh c\u00f4ng hay kh\u00f4ng.</div>\n  </div>\n  <div class=\"card-full\" style=\"margin-bottom:18px;border-color:rgba(16,185,129,.25)\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">C\u00e2u h\u1ecfi 3 \u00b7 Training c\u00f3 ph\u1ea3i gi\u1ea3i ph\u00e1p \u0111\u00fang kh\u00f4ng?</div>\n    <div class=\"ct\">\u0110\u00f4i khi c\u00e2u tr\u1ea3 l\u1eddi l\u00e0: kh\u00f4ng c\u1ea7n training, c\u1ea7n th\u1ee9 kh\u00e1c</div>\n    <div class=\"cd\" style=\"margin-top:6px\">Nh\u00e2n vi\u00ean b\u00e1n h\u00e0ng kh\u00f4ng hit target \u2192 training th\u00eam? Ho\u1eb7c: target kh\u00f4ng th\u1ef1c t\u1ebf, territory kh\u00f4ng t\u1ed1t, tool CRM k\u00e9m, kh\u00f4ng c\u00f3 incentive \u0111\u00fang? Ki\u1ec3m tra performance driver tr\u01b0\u1edbc khi thi\u1ebft k\u1ebf curriculum.</div>\n  </div>\n\n  <div class=\"sec-title\">Ma tr\u1eadn TNA \u2014 4 \u00f4 quy\u1ebft \u0111\u1ecbnh</div>\n  <div class=\"ex\" style=\"margin-top:0\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83d\uddfa\ufe0f</div>\n      <div><div class=\"ex-label\">Ph\u00e2n lo\u1ea1i t\u00ecnh hu\u1ed1ng</div><div class=\"ex-sub\">Click v\u00e0o \u00f4 ph\u00f9 h\u1ee3p v\u1edbi t\u00ecnh hu\u1ed1ng b\u00ean d\u01b0\u1edbi</div></div>\n    </div>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:12px\"><b style=\"color:var(--text)\">T\u00ecnh hu\u1ed1ng:</b> Nh\u00e2n vi\u00ean b\u1ebfp m\u1eafc l\u1ed7i v\u1ec7 sinh th\u1ef1c ph\u1ea9m l\u1eb7p l\u1ea1i. Manager b\u00e1o c\u00e1o r\u1eb1ng h\u1ecd \u0111\u00e3 \u0111\u01b0\u1ee3c training nh\u01b0ng v\u1eabn ti\u1ebfp t\u1ee5c sai. Supervisor cho bi\u1ebft nh\u00e2n vi\u00ean bi\u1ebft quy t\u1eafc nh\u01b0ng \"kh\u00f4ng \u0111\u1ec3 \u00fd\".</p>\n    <div class=\"tna-grid\">\n      <div class=\"tna-cell\" id=\"tna-A\" onclick=\"pickTNA('A')\">\n        <div class=\"tna-label\">Thi\u1ebfu ki\u1ebfn th\u1ee9c / k\u1ef9 n\u0103ng</div>\n        <div class=\"tna-text\">Ch\u01b0a bi\u1ebft quy t\u1eafc, ch\u01b0a \u0111\u01b0\u1ee3c h\u1ecdc \u2192 c\u1ea7n training</div>\n      </div>\n      <div class=\"tna-cell\" id=\"tna-B\" onclick=\"pickTNA('B')\">\n        <div class=\"tna-label\">Thi\u1ebfu \u0111\u1ed9ng l\u1ef1c / accountability</div>\n        <div class=\"tna-text\">Bi\u1ebft nh\u01b0ng kh\u00f4ng l\u00e0m \u2192 c\u1ea7n consequence, feedback, ho\u1eb7c incentive</div>\n      </div>\n      <div class=\"tna-cell\" id=\"tna-C\" onclick=\"pickTNA('C')\">\n        <div class=\"tna-label\">V\u1ea5n \u0111\u1ec1 quy tr\u00ecnh / m\u00f4i tr\u01b0\u1eddng</div>\n        <div class=\"tna-text\">Mu\u1ed1n l\u00e0m \u0111\u00fang nh\u01b0ng h\u1ec7 th\u1ed1ng c\u1ea3n tr\u1edf \u2192 c\u1ea7n fix quy tr\u00ecnh</div>\n      </div>\n      <div class=\"tna-cell\" id=\"tna-D\" onclick=\"pickTNA('D')\">\n        <div class=\"tna-label\">C\u1ea7n c\u1ea3 training l\u1eabn h\u1ec7 th\u1ed1ng</div>\n        <div class=\"tna-text\">Gap k\u00e9p \u2014 training + thay \u0111\u1ed5i m\u00f4i tr\u01b0\u1eddng l\u00e0m vi\u1ec7c</div>\n      </div>\n    </div>\n    <div class=\"qfb\" id=\"qf1\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 1</div>\n    <div class=\"tw-text\">\"Training kh\u00f4ng ph\u1ea3i gi\u1ea3i ph\u00e1p cho m\u1ecdi v\u1ea5n \u0111\u1ec1 hi\u1ec7u su\u1ea5t. C\u00e2u h\u1ecfi \u0111\u1ea7u ti\u00ean c\u1ee7a L&D kh\u00f4ng ph\u1ea3i 'c\u1ea7n training g\u00ec' \u2014 m\u00e0 l\u00e0 'v\u1ea5n \u0111\u1ec1 th\u1eadt s\u1ef1 l\u00e0 g\u00ec v\u00e0 training c\u00f3 ph\u1ea3i c\u00e2u tr\u1ea3 l\u1eddi \u0111\u00fang kh\u00f4ng.'\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" disabled>\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n1\" onclick=\"go(2)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h1\">Ch\u1ecdn \u00f4 trong ma tr\u1eadn TNA \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550 M2 \u2014 ADDIE \u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m2\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 2 / 6</div>\n      <div class=\"hero-title\">ADDIE \u2014 thi\u1ebft k\u1ebf b\u00e0i gi\u1ea3ng cho F&B chain</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"L&D specialist m\u1edbi v\u00e0o team c\u1ee7a Hi\u1ec1n h\u1ecfi: 'Ch\u1ecb \u01a1i, em mu\u1ed1n thi\u1ebft k\u1ebf training cho nh\u00e2n vi\u00ean b\u00e1n h\u00e0ng, b\u1eaft \u0111\u1ea7u t\u1eeb \u0111\u00e2u?' Hi\u1ec1n h\u1ecfi l\u1ea1i: 'Em mu\u1ed1n h\u1ecd l\u00e0m \u0111\u01b0\u1ee3c g\u00ec sau training m\u00e0 hi\u1ec7n t\u1ea1i h\u1ecd ch\u01b0a l\u00e0m \u0111\u01b0\u1ee3c?' \u2014 Im l\u1eb7ng d\u00e0i. 'Em ch\u01b0a ngh\u0129 \u0111\u1ebfn \u0111i\u1ec1u \u0111\u00f3.' \u2014 \u0110\u00f3 l\u00e0 l\u00fd do 70% training kh\u00f4ng t\u1ea1o ra thay \u0111\u1ed5i: ng\u01b0\u1eddi thi\u1ebft k\u1ebf b\u1eaft \u0111\u1ea7u t\u1eeb n\u1ed9i dung, kh\u00f4ng ph\u1ea3i t\u1eeb k\u1ebft qu\u1ea3.\"</div>\n\n  <p class=\"body\">ADDIE l\u00e0 framework thi\u1ebft k\u1ebf instructional design ti\u00eau chu\u1ea9n \u2014 kh\u00f4ng ph\u1ea3i \u0111\u1ec3 l\u00e0m ph\u1ee9c t\u1ea1p h\u01a1n, m\u00e0 \u0111\u1ec3 <b>\u0111\u1ea3m b\u1ea3o training \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf backward t\u1eeb k\u1ebft qu\u1ea3</b>, kh\u00f4ng forward t\u1eeb n\u1ed9i dung.</p>\n\n  <div class=\"sec-title\">ADDIE th\u1ef1c chi\u1ebfn \u2014 5 b\u01b0\u1edbc \u00e1p d\u1ee5ng cho F&B</div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">A \u2014 Analyze (Ph\u00e2n t\u00edch)</div>\n    <div class=\"ct\">\u0110\u00e3 l\u00e0m \u1edf b\u00e0i TNA \u2014 x\u00e1c \u0111\u1ecbnh gap v\u00e0 behavioral outcome</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Output: \"Sau training, nh\u00e2n vi\u00ean X s\u1ebd l\u00e0m \u0111\u01b0\u1ee3c Y trong Z% tr\u01b0\u1eddng h\u1ee3p.\" N\u1ebfu kh\u00f4ng c\u00f3 c\u00e2u n\u00e0y r\u00f5 r\u00e0ng \u2014 kh\u00f4ng chuy\u1ec3n sang b\u01b0\u1edbc ti\u1ebfp theo.</div>\n  </div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">D \u2014 Design (Thi\u1ebft k\u1ebf)</div>\n    <div class=\"ct\">Ch\u1ecdn ph\u01b0\u01a1ng ph\u00e1p, format, v\u00e0 sequence h\u1ecdc</div>\n    <div class=\"cd\" style=\"margin-top:5px\">V\u1edbi F&B chain: nh\u00e2n vi\u00ean turnover cao, \u00edt th\u1eddi gian \u2192 microlearning 15\u201320 ph\u00fat, scenario-based, \u00edt text nhi\u1ec1u visual v\u00e0 demo. Sequence: why (t\u1ea1i sao quan tr\u1ecdng) \u2192 what (kh\u00e1i ni\u1ec7m ng\u1eafn) \u2192 how (demo) \u2192 practice \u2192 apply.</div>\n  </div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">D \u2014 Develop (Ph\u00e1t tri\u1ec3n n\u1ed9i dung)</div>\n    <div class=\"ct\">Build content theo design \u2014 kh\u00f4ng ph\u1ea3i build r\u1ed3i m\u1edbi design</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Prototype tr\u01b0\u1edbc: 1 module nh\u1ecf \u2192 test v\u1edbi 3\u20135 ng\u01b0\u1eddi \u2192 \u0111i\u1ec1u ch\u1ec9nh \u2192 build to\u00e0n b\u1ed9. D\u00f9ng AI \u0111\u1ec3 generate draft nhanh (xem K3), nh\u01b0ng HR review v\u00e0 add context t\u1ed5 ch\u1ee9c.</div>\n  </div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">I \u2014 Implement (Tri\u1ec3n khai)</div>\n    <div class=\"ct\">Pilot tr\u01b0\u1edbc khi rollout to\u00e0n t\u1ed5 ch\u1ee9c</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Pilot v\u1edbi 1 c\u1eeda h\u00e0ng ho\u1eb7c 1 team nh\u1ecf \u2192 \u0111o k\u1ebft qu\u1ea3 \u2192 \u0111i\u1ec1u ch\u1ec9nh \u2192 rollout. Kh\u00f4ng tri\u1ec3n khai \u0111\u1ea1i tr\u00e0 ngay khi ch\u01b0a test. Brief manager v\u1ec1 vai tr\u00f2 c\u1ee7a h\u1ecd trong reinforcement sau training.</div>\n  </div>\n  <div class=\"card-full\" style=\"margin-bottom:18px\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">E \u2014 Evaluate (\u0110\u00e1nh gi\u00e1)</div>\n    <div class=\"ct\">\u0110o theo Kirkpatrick 4 levels \u2014 kh\u00f4ng ch\u1ec9 reaction survey</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Xem chi ti\u1ebft \u1edf b\u00e0i 5. Key point: evaluation ph\u1ea3i \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf t\u1eeb b\u01b0\u1edbc Analyze \u2014 kh\u00f4ng ph\u1ea3i t\u1ef1 h\u1ecfi \"\u0111o g\u00ec\" sau khi training \u0111\u00e3 xong.</div>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83c\udfaf</div>\n      <div><div class=\"ex-label\">Ki\u1ec3m tra ADDIE</div><div class=\"ex-sub\">X\u00e1c \u0111\u1ecbnh b\u01b0\u1edbc n\u00e0o b\u1ecb b\u1ecf qua</div></div>\n    </div>\n    <div class=\"qq\">L&D team nh\u1eadn y\u00eau c\u1ea7u t\u1eeb Ops Director: \"Th\u00e1ng sau l\u00e0m training customer service cho to\u00e0n b\u1ed9 300 nh\u00e2n vi\u00ean ph\u1ee5c v\u1ee5, tr\u01b0\u1edbc m\u00f9a cao \u0111i\u1ec3m.\" L&D b\u1eaft \u0111\u1ea7u ngay b\u1eb1ng c\u00e1ch t\u00ecm n\u1ed9i dung v\u00e0 thi\u1ebft k\u1ebf slide. H\u1ecd \u0111\u00e3 b\u1ecf qua b\u01b0\u1edbc n\u00e0o quan tr\u1ecdng nh\u1ea5t?</div>\n    <div class=\"qopts\" id=\"q2opts\">\n      <button class=\"qopt\" onclick=\"AQ(2,this,'A')\"><span class=\"oletter\">A</span>Develop \u2014 n\u00ean t\u00ecm template c\u00f3 s\u1eb5n thay v\u00ec t\u1ef1 thi\u1ebft k\u1ebf slide</button>\n      <button class=\"qopt\" onclick=\"AQ(2,this,'B')\"><span class=\"oletter\">B</span>Analyze \u2014 ch\u01b0a x\u00e1c \u0111\u1ecbnh gap c\u1ee5 th\u1ec3, behavioral outcome, v\u00e0 li\u1ec7u training c\u00f3 ph\u1ea3i gi\u1ea3i ph\u00e1p \u0111\u00fang</button>\n      <button class=\"qopt\" onclick=\"AQ(2,this,'C')\"><span class=\"oletter\">C</span>Implement \u2014 n\u00ean pilot tr\u01b0\u1edbc v\u1edbi 1 c\u1eeda h\u00e0ng thay v\u00ec rollout 300 ng\u01b0\u1eddi ngay</button>\n      <button class=\"qopt\" onclick=\"AQ(2,this,'D')\"><span class=\"oletter\">D</span>Evaluate \u2014 ch\u01b0a chu\u1ea9n b\u1ecb kh\u1ea3o s\u00e1t sau training</button>\n    </div>\n    <div class=\"qfb\" id=\"qf2\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 2</div>\n    <div class=\"tw-text\">\"Training \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf t\u1eeb n\u1ed9i dung th\u01b0\u1eddng d\u1ea1y th\u1ee9 L&D bi\u1ebft \u2014 kh\u00f4ng ph\u1ea3i th\u1ee9 ng\u01b0\u1eddi h\u1ecdc c\u1ea7n l\u00e0m \u0111\u01b0\u1ee3c. B\u1eaft \u0111\u1ea7u t\u1eeb behavioral outcome, r\u1ed3i m\u1edbi ch\u1ecdn n\u1ed9i dung.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(1)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n2\" onclick=\"go(3)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h2\">Tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550 M3 \u2014 Facilitation \u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m3\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 3 / 6</div>\n      <div class=\"hero-title\">Facilitation skills \u2014 d\u1eabn d\u1eaft l\u1edbp h\u1ecdc live hi\u1ec7u qu\u1ea3</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Hi\u1ec1n t\u1eebng quan s\u00e1t m\u1ed9t L&D specialist d\u1eabn training 4 ti\u1ebfng cho 40 nh\u00e2n vi\u00ean b\u00e1n h\u00e0ng. Ng\u01b0\u1eddi facilitator \u0111\u1ecdc slide t\u1eeb \u0111\u1ea7u \u0111\u1ebfn cu\u1ed1i, gi\u1ecdng \u0111\u1ec1u \u0111\u1ec1u, kh\u00f4ng c\u00f3 ho\u1ea1t \u0111\u1ed9ng n\u00e0o. Sau 2 ti\u1ebfng, 30% ph\u00f2ng \u0111ang nh\u00ecn \u0111i\u1ec7n tho\u1ea1i. Sau 4 ti\u1ebfng, kh\u00f4ng ai nh\u1edb g\u00ec. Ki\u1ebfn th\u1ee9c v\u1ec1 customer service r\u1ea5t t\u1ed1t \u2014 nh\u01b0ng facilitation k\u00e9m \u0111\u00e3 gi\u1ebft ch\u1ebft to\u00e0n b\u1ed9 gi\u00e1 tr\u1ecb c\u1ee7a n\u1ed9i dung \u0111\u00f3.\"</div>\n\n  <p class=\"body\">Facilitation kh\u00e1c v\u1edbi presentation. Presenter truy\u1ec1n th\u00f4ng tin \u2014 facilitator <b>t\u1ea1o ra tr\u1ea3i nghi\u1ec7m h\u1ecdc t\u1eadp</b>. Ng\u01b0\u1eddi h\u1ecdc kh\u00f4ng nh\u1edb nh\u1eefng g\u00ec h\u1ecd nghe \u2014 h\u1ecd nh\u1edb nh\u1eefng g\u00ec h\u1ecd l\u00e0m, c\u1ea3m nh\u1eadn, v\u00e0 t\u1ef1 kh\u00e1m ph\u00e1.</p>\n\n  <div class=\"sec-title\">5 k\u1ef9 thu\u1eadt facilitation th\u1ef1c chi\u1ebfn</div>\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">K\u1ef9 thu\u1eadt 1</div>\n      <div class=\"ct\">Open v\u1edbi hook \u2014 kh\u00f4ng v\u1edbi agenda</div>\n      <div class=\"cd\">30 gi\u00e2y \u0111\u1ea7u quy\u1ebft \u0111\u1ecbnh engagement. \u0110\u1eebng m\u1edf b\u1eb1ng \"H\u00f4m nay ch\u00fang ta s\u1ebd h\u1ecdc v\u1ec1...\" \u2014 m\u1edf b\u1eb1ng c\u00e2u h\u1ecfi, t\u00ecnh hu\u1ed1ng, ho\u1eb7c s\u1ed1 li\u1ec7u g\u00e2y shock nh\u1eb9 \u0111\u1ec3 ng\u01b0\u1eddi h\u1ecdc ngh\u0129 ngay t\u1eeb \u0111\u1ea7u</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">K\u1ef9 thu\u1eadt 2</div>\n      <div class=\"ct\">Think-pair-share m\u1ed7i 15\u201320 ph\u00fat</div>\n      <div class=\"cd\">\u0110\u1eb7t c\u00e2u h\u1ecfi \u2192 2 ph\u00fat ngh\u0129 c\u00e1 nh\u00e2n \u2192 chia s\u1ebb v\u1edbi ng\u01b0\u1eddi b\u00ean c\u1ea1nh \u2192 b\u00e1o c\u00e1o nh\u00f3m. Ph\u00e1 v\u1ee1 th\u1ee5 \u0111\u1ed9ng, bu\u1ed9c t\u1ea5t c\u1ea3 tham gia, L&D nghe \u0111\u01b0\u1ee3c c\u1ea3 ph\u00f2ng ngh\u0129 g\u00ec</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">K\u1ef9 thu\u1eadt 3</div>\n      <div class=\"ct\">Role-play scenario th\u1ef1c t\u1ebf</div>\n      <div class=\"cd\">T\u00ecnh hu\u1ed1ng t\u1eeb c\u1eeda h\u00e0ng th\u1eadt, nh\u00e2n v\u1eadt quen thu\u1ed9c. \"B\u1ea1n l\u00e0 nh\u00e2n vi\u00ean ph\u1ee5c v\u1ee5, kh\u00e1ch v\u1eeba ph\u00e0n n\u00e0n m\u00f3n \u0103n ngu\u1ed9i \u2014 b\u1ea1n n\u00f3i g\u00ec?\" \u2014 Th\u1ef1c h\u00e0nh ngay trong l\u1edbp</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">K\u1ef9 thu\u1eadt 4</div>\n      <div class=\"ct\">X\u1eed l\u00fd \"ng\u01b0\u1eddi kh\u00f3\" trong ph\u00f2ng</div>\n      <div class=\"cd\">Ng\u01b0\u1eddi im l\u1eb7ng su\u1ed1t: \"Anh Nam, theo kinh nghi\u1ec7m c\u1ee7a anh th\u00ec sao?\" Ng\u01b0\u1eddi ph\u1ea3n \u0111\u1ed1i: \"C\u1ea3m \u01a1n anh \u0111\u00e3 chia s\u1ebb \u2014 c\u00f3 ai trong ph\u00f2ng c\u00f3 g\u00f3c nh\u00ecn kh\u00e1c kh\u00f4ng?\" Kh\u00f4ng \u0111\u1ed1i \u0111\u1ea7u tr\u1ef1c ti\u1ebfp</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">K\u1ef9 thu\u1eadt 5</div>\n      <div class=\"ct\">Closing: action commitment</div>\n      <div class=\"cd\">K\u1ebft th\u00fac kh\u00f4ng ph\u1ea3i \"t\u00f3m t\u1eaft n\u1ed9i dung\" \u2014 m\u00e0 l\u00e0 \"b\u1ea1n s\u1ebd l\u00e0m g\u00ec kh\u00e1c \u0111i t\u1eeb ng\u00e0y mai?\" M\u1ed7i ng\u01b0\u1eddi cam k\u1ebft 1 h\u00e0nh \u0111\u1ed9ng c\u1ee5 th\u1ec3 tr\u01b0\u1edbc khi r\u1eddi ph\u00f2ng</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\">\u0110\u1eebng l\u00e0m</div>\n      <div class=\"ct\">Death by PowerPoint</div>\n      <div class=\"cd\">Slide > 10 bullet points, \u0111\u1ecdc nguy\u00ean v\u0103n t\u1eeb slide, kh\u00f4ng c\u00f3 kho\u1ea3ng tr\u1eafng \u0111\u1ec3 ng\u01b0\u1eddi h\u1ecdc x\u1eed l\u00fd. Quy t\u1eafc: 1 idea/slide, t\u1ed1i \u0111a 6 words/bullet, visual > text</div>\n    </div>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83c\udfad</div>\n      <div><div class=\"ex-label\">T\u00ecnh hu\u1ed1ng facilitation kh\u00f3</div><div class=\"ex-sub\">Ch\u1ecdn c\u00e1ch x\u1eed l\u00fd t\u1ed1t nh\u1ea5t</div></div>\n    </div>\n    <div class=\"qq\">Trong l\u1edbp training 30 ng\u01b0\u1eddi, sau 90 ph\u00fat m\u1ed9t nh\u00e2n vi\u00ean l\u00e2u n\u0103m n\u00f3i to: \"M\u1ea5y c\u00e1i n\u00e0y l\u00fd thuy\u1ebft qu\u00e1, th\u1ef1c t\u1ebf kh\u00f4ng \u00e1p d\u1ee5ng \u0111\u01b0\u1ee3c \u0111\u00e2u.\" C\u1ea3 ph\u00f2ng im l\u1eb7ng nh\u00ecn b\u1ea1n. B\u1ea1n x\u1eed l\u00fd th\u1ebf n\u00e0o?</div>\n    <div class=\"qopts\" id=\"q3opts\">\n      <button class=\"qopt\" onclick=\"AQ(3,this,'A')\"><span class=\"oletter\">A</span>Gi\u1ea3i th\u00edch t\u1ea1i sao n\u1ed9i dung n\u00e0y th\u1ef1c t\u1ebf v\u00e0 c\u00f3 th\u1ec3 \u00e1p d\u1ee5ng \u0111\u01b0\u1ee3c</button>\n      <button class=\"qopt\" onclick=\"AQ(3,this,'B')\"><span class=\"oletter\">B</span>H\u1ecfi: \"Anh c\u00f3 th\u1ec3 k\u1ec3 cho c\u1ea3 l\u1edbp nghe t\u00ecnh hu\u1ed1ng c\u1ee5 th\u1ec3 n\u00e0o anh th\u1ea5y kh\u00f3 \u00e1p d\u1ee5ng kh\u00f4ng? M\u00ecnh c\u00f9ng gi\u1ea3i quy\u1ebft\"</button>\n      <button class=\"qopt\" onclick=\"AQ(3,this,'C')\"><span class=\"oletter\">C</span>Ti\u1ebfp t\u1ee5c b\u00e0i gi\u1ea3ng v\u00e0 b\u1ecf qua comment \u0111\u00f3 \u0111\u1ec3 kh\u00f4ng m\u1ea5t th\u1eddi gian</button>\n      <button class=\"qopt\" onclick=\"AQ(3,this,'D')\"><span class=\"oletter\">D</span>N\u00f3i: \"Feedback c\u1ee7a anh r\u1ea5t qu\u00fd \u2014 sau l\u1edbp m\u00ecnh n\u00f3i chuy\u1ec7n th\u00eam nh\u00e9\"</button>\n    </div>\n    <div class=\"qfb\" id=\"qf3\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 3</div>\n    <div class=\"tw-text\">\"Facilitator gi\u1ecfi kh\u00f4ng ph\u1ea3i ng\u01b0\u1eddi bi\u1ebft nhi\u1ec1u nh\u1ea5t trong ph\u00f2ng \u2014 m\u00e0 l\u00e0 ng\u01b0\u1eddi gi\u1ecfi nh\u1ea5t trong vi\u1ec7c khai th\u00e1c ki\u1ebfn th\u1ee9c v\u00e0 kinh nghi\u1ec7m c\u1ee7a nh\u1eefng ng\u01b0\u1eddi trong ph\u00f2ng.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(2)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n3\" onclick=\"go(4)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h3\">Tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550 M4 \u2014 Format \u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m4\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 4 / 6</div>\n      <div class=\"hero-title\">E-learning, ILT, Microlearning \u2014 khi n\u00e0o d\u00f9ng c\u00e1i g\u00ec</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"CEO c\u1ee7a m\u1ed9t chu\u1ed7i F&B 120 c\u1eeda h\u00e0ng h\u1ecfi Hi\u1ec1n: 'M\u00ecnh c\u00f3 n\u00ean \u0111\u1ea7u t\u01b0 v\u00e0o LMS v\u00e0 e-learning kh\u00f4ng? Nghe n\u00f3i ti\u1ebft ki\u1ec7m chi ph\u00ed training nhi\u1ec1u l\u1eafm.' Hi\u1ec1n h\u1ecfi l\u1ea1i: 'Training v\u1ec1 g\u00ec? Cho ai? K\u1ebft qu\u1ea3 mong mu\u1ed1n l\u00e0 g\u00ec?' CEO tr\u1ea3 l\u1eddi kh\u00f4ng r\u00f5. Hi\u1ec1n n\u00f3i: 'C\u00e2u tr\u1ea3 l\u1eddi ph\u1ee5 thu\u1ed9c v\u00e0o 3 c\u00e2u \u0111\u00f3 \u2014 kh\u00f4ng ph\u1ea3i v\u00e0o xu h\u01b0\u1edbng.'\"</div>\n\n  <p class=\"body\">Kh\u00f4ng c\u00f3 format n\u00e0o t\u1ed1t h\u01a1n t\u1ea5t c\u1ea3 \u2014 ch\u1ec9 c\u00f3 format <b>ph\u00f9 h\u1ee3p hay kh\u00f4ng ph\u00f9 h\u1ee3p v\u1edbi m\u1ee5c ti\u00eau h\u1ecdc t\u1eadp, \u0111\u1ed1i t\u01b0\u1ee3ng, v\u00e0 ng\u00e2n s\u00e1ch</b>. Ch\u1ecdn sai format = content t\u1ed1t c\u0169ng b\u1ecb waste.</p>\n\n  <div class=\"sec-title\">So s\u00e1nh 4 format h\u1ecdc t\u1eadp ch\u00ednh</div>\n  <div class=\"grid2\">\n    <div class=\"card\" style=\"border-color:rgba(16,185,129,.25)\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">ILT \u00b7 Instructor-Led Training</div>\n      <div class=\"ct\">T\u1ed1t nh\u1ea5t cho: k\u1ef9 n\u0103ng m\u1ec1m, attitude, team building</div>\n      <div class=\"cd\">C\u1ea7n: th\u1ea3o lu\u1eadn, role-play, trust building. Kh\u00f4ng th\u1ec3 thay th\u1ebf khi training li\u00ean quan \u0111\u1ebfn c\u1ea3m x\u00fac, v\u0103n h\u00f3a, ho\u1eb7c practice hands-on. Chi ph\u00ed cao \u2014 nh\u01b0ng impact cao nh\u1ea5t n\u1ebfu facilitate \u0111\u00fang</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--cyan)\">E-learning / LMS</div>\n      <div class=\"ct\">T\u1ed1t nh\u1ea5t cho: ki\u1ebfn th\u1ee9c chu\u1ea9n h\u00f3a, compliance, onboarding process</div>\n      <div class=\"cd\">C\u1ea7n: n\u1ed9i dung \u1ed5n \u0111\u1ecbnh, kh\u00f4ng c\u1ea7n th\u1ea3o lu\u1eadn, reach nhi\u1ec1u ng\u01b0\u1eddi c\u00f9ng l\u00fac. Kh\u00f4ng ph\u00f9 h\u1ee3p cho k\u1ef9 n\u0103ng m\u1ec1m \u2014 ng\u01b0\u1eddi h\u1ecdc ho\u00e0n th\u00e0nh quiz m\u00e0 kh\u00f4ng thay \u0111\u1ed5i h\u00e0nh vi</div>\n    </div>\n    <div class=\"card\" style=\"border-color:rgba(240,192,64,.25)\">\n      <div class=\"cn\" style=\"color:var(--gold)\">Microlearning</div>\n      <div class=\"ct\">T\u1ed1t nh\u1ea5t cho: reinforcement, just-in-time learning, reminder</div>\n      <div class=\"cd\">3\u20137 ph\u00fat, 1 concept, mobile-first. Kh\u00f4ng thay th\u1ebf \u0111\u01b0\u1ee3c ILT \u2014 d\u00f9ng \u0111\u1ec3 reinforce sau training ch\u00ednh. R\u1ea5t hi\u1ec7u qu\u1ea3 v\u1edbi nh\u00e2n vi\u00ean F&B hay d\u00f9ng \u0111i\u1ec7n tho\u1ea1i</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--muted)\">OJT \u00b7 On-the-Job Training</div>\n      <div class=\"ct\">T\u1ed1t nh\u1ea5t cho: k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt, procedure, hands-on</div>\n      <div class=\"cd\">H\u1ecdc b\u1eb1ng l\u00e0m d\u01b0\u1edbi s\u1ef1 h\u01b0\u1edbng d\u1eabn. Hi\u1ec7u qu\u1ea3 nh\u1ea5t cho v\u1eadn h\u00e0nh \u2014 nh\u01b0ng c\u1ea7n trainer \u0111\u01b0\u1ee3c train \u0111\u1ec3 kh\u00f4ng truy\u1ec1n sai k\u1ef9 thu\u1eadt v\u00e0 bad habit</div>\n    </div>\n  </div>\n\n  <div class=\"hl\">\n    <div class=\"hl-label\">Blended learning \u2014 k\u1ebft h\u1ee3p t\u1ed1i \u01b0u cho F&B chain</div>\n    <p style=\"margin-bottom:7px\"><b style=\"color:var(--emerald)\">Pre-work (E-learning 15 ph\u00fat):</b> Ki\u1ebfn th\u1ee9c n\u1ec1n \u2192 \u0111\u1ebfn l\u1edbp kh\u00f4ng ph\u1ea3i gi\u1ea3i th\u00edch t\u1eeb \u0111\u1ea7u</p>\n    <p style=\"margin-bottom:7px\"><b style=\"color:var(--emerald)\">Core (ILT 2 ti\u1ebfng):</b> Practice, discussion, role-play \u2192 t\u1ea1o ra thay \u0111\u1ed5i h\u00e0nh vi</p>\n    <p><b style=\"color:var(--emerald)\">Post (Microlearning 3 ph\u00fat/tu\u1ea7n \u00d7 4 tu\u1ea7n):</b> Reinforcement \u2192 ch\u1ed1ng forgetting curve</p>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83c\udfae</div>\n      <div><div class=\"ex-label\">Ch\u1ecdn format ph\u00f9 h\u1ee3p</div><div class=\"ex-sub\">Click v\u00e0o format t\u1ed1t nh\u1ea5t cho t\u1eebng t\u00ecnh hu\u1ed1ng</div></div>\n    </div>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:12px\"><b style=\"color:var(--text)\">T\u00ecnh hu\u1ed1ng:</b> Chu\u1ed7i v\u1eeba thay \u0111\u1ed5i quy tr\u00ecnh t\u00ednh ti\u1ec1n \u2014 c\u1ea7n 500 nh\u00e2n vi\u00ean thu ng\u00e2n tr\u00ean 50 c\u1eeda h\u00e0ng bi\u1ebft quy tr\u00ecnh m\u1edbi tr\u01b0\u1edbc khi \u00e1p d\u1ee5ng v\u00e0o tu\u1ea7n t\u1edbi. Kh\u00f4ng c\u00f3 ng\u00e2n s\u00e1ch cho trainer \u0111i t\u1eebng c\u1eeda h\u00e0ng.</p>\n    <div class=\"fmt-opts\" id=\"fmt4\">\n      <div class=\"fmt-card\" onclick=\"pickFmt(this,'bad')\">\n        <div class=\"fmt-title\">ILT t\u1eadp trung</div>\n        <div class=\"fmt-desc\">T\u1eadp h\u1ee3p t\u1ea5t c\u1ea3 v\u1ec1 1 \u0111\u1ecba \u0111i\u1ec3m \u0111\u1ec3 trainer gi\u1ea3ng tr\u1ef1c ti\u1ebfp</div>\n      </div>\n      <div class=\"fmt-card\" onclick=\"pickFmt(this,'good')\">\n        <div class=\"fmt-title\">E-learning + video demo</div>\n        <div class=\"fmt-desc\">Clip demo 10 ph\u00fat + quiz ki\u1ec3m tra \u2014 t\u1ef1 h\u1ecdc tr\u00ean \u0111i\u1ec7n tho\u1ea1i</div>\n      </div>\n      <div class=\"fmt-card\" onclick=\"pickFmt(this,'bad')\">\n        <div class=\"fmt-title\">Microlearning tips</div>\n        <div class=\"fmt-desc\">G\u1eedi tips nh\u1ecf h\u00e0ng ng\u00e0y qua Zalo/nh\u00f3m chat</div>\n      </div>\n      <div class=\"fmt-card\" onclick=\"pickFmt(this,'bad')\">\n        <div class=\"fmt-title\">OJT v\u1edbi buddy</div>\n        <div class=\"fmt-desc\">Nh\u00e2n vi\u00ean c\u0169 h\u01b0\u1edbng d\u1eabn tr\u1ef1c ti\u1ebfp ng\u01b0\u1eddi m\u1edbi t\u1ea1i qu\u1ea7y</div>\n      </div>\n    </div>\n    <div class=\"qfb\" id=\"qf4\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 4</div>\n    <div class=\"tw-text\">\"Format kh\u00f4ng quan tr\u1ecdng b\u1eb1ng fit. E-learning kh\u00f4ng k\u00e9m h\u01a1n ILT \u2014 n\u00f3 ch\u1ec9 ph\u00f9 h\u1ee3p v\u1edbi m\u1ee5c ti\u00eau h\u1ecdc t\u1eadp kh\u00e1c. Ch\u1ecdn format d\u1ef1a tr\u00ean 'ng\u01b0\u1eddi h\u1ecdc c\u1ea7n l\u00e0m \u0111\u01b0\u1ee3c g\u00ec', kh\u00f4ng ph\u1ea3i 'format n\u00e0o trendy.'\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(3)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n4\" onclick=\"go(5)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h4\">Ch\u1ecdn format \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550 M5 \u2014 Kirkpatrick \u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m5\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 5 / 6</div>\n      <div class=\"hero-title\">Kirkpatrick 4 levels \u2014 \u0111o ROI training th\u1ef1c chi\u1ebfn</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Sau m\u1ed7i training, L&D team g\u1eedi survey: 'B\u1ea1n th\u1ea5y training n\u00e0y th\u1ebf n\u00e0o? 1\u20135 sao.' Trung b\u00ecnh lu\u00f4n 4.2/5. CEO h\u1ecfi: 'Training c\u00f3 hi\u1ec7u qu\u1ea3 kh\u00f4ng?' L&D tr\u1ea3 l\u1eddi: 'Nh\u00e2n vi\u00ean r\u1ea5t th\u00edch.' CEO g\u1eadt \u0111\u1ea7u nh\u01b0ng kh\u00f4ng satisfied. N\u0103m sau c\u1eaft 30% ng\u00e2n s\u00e1ch training. L\u00fd do: 'Kh\u00f4ng th\u1ea5y impact.' \u0110\u00f3 l\u00e0 h\u1eadu qu\u1ea3 c\u1ee7a vi\u1ec7c ch\u1ec9 \u0111o Level 1.\"</div>\n\n  <p class=\"body\">Kirkpatrick Model 4 levels l\u00e0 framework \u0111o hi\u1ec7u qu\u1ea3 training to\u00e0n di\u1ec7n nh\u1ea5t \u2014 \u0111\u01b0\u1ee3c d\u00f9ng t\u1eeb 1959 \u0111\u1ebfn nay. V\u1ea5n \u0111\u1ec1 kh\u00f4ng ph\u1ea3i model \u2014 v\u1ea5n \u0111\u1ec1 l\u00e0 h\u1ea7u h\u1ebft L&D ch\u1ec9 \u0111o Level 1 v\u00ec Level 2, 3, 4 kh\u00f3 \u0111o h\u01a1n.</p>\n\n  <div class=\"sec-title\">4 levels \u2014 t\u1eeb d\u1ec5 nh\u1ea5t \u0111\u1ebfn c\u00f3 gi\u00e1 tr\u1ecb nh\u1ea5t</div>\n\n  <div class=\"kp-levels\">\n    <div class=\"kp-level\">\n      <div class=\"kp-name\">Level 1 \u00b7 Reaction</div>\n      <div class=\"kp-bar-wrap\"><div class=\"kp-bar\" style=\"width:95%;background:rgba(239,68,68,.6)\"></div></div>\n      <div class=\"kp-pct\">95% d\u00f9ng</div>\n    </div>\n    <div class=\"kp-level\">\n      <div class=\"kp-name\">Level 2 \u00b7 Learning</div>\n      <div class=\"kp-bar-wrap\"><div class=\"kp-bar\" style=\"width:60%;background:rgba(249,115,22,.6)\"></div></div>\n      <div class=\"kp-pct\">60% d\u00f9ng</div>\n    </div>\n    <div class=\"kp-level\">\n      <div class=\"kp-name\">Level 3 \u00b7 Behavior</div>\n      <div class=\"kp-bar-wrap\"><div class=\"kp-bar\" style=\"width:30%;background:rgba(240,192,64,.6)\"></div></div>\n      <div class=\"kp-pct\">30% d\u00f9ng</div>\n    </div>\n    <div class=\"kp-level\">\n      <div class=\"kp-name\">Level 4 \u00b7 Results</div>\n      <div class=\"kp-bar-wrap\"><div class=\"kp-bar\" style=\"width:15%;background:rgba(16,185,129,.7)\"></div></div>\n      <div class=\"kp-pct\">15% d\u00f9ng</div>\n    </div>\n  </div>\n\n  <div class=\"grid2\">\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--red)\">Level 1 \u00b7 Reaction</div>\n      <div class=\"ct\">Ng\u01b0\u1eddi h\u1ecdc c\u1ea3m th\u1ea5y th\u1ebf n\u00e0o?</div>\n      <div class=\"cd\">Survey ngay sau training. \u0110o: satisfaction, perceived relevance. H\u1ea1n ch\u1ebf: \"th\u00edch\" kh\u00f4ng c\u00f3 ngh\u0129a l\u00e0 \"h\u1ecdc \u0111\u01b0\u1ee3c\" hay \"thay \u0111\u1ed5i h\u00e0nh vi\"</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cn\" style=\"color:var(--gold)\">Level 2 \u00b7 Learning</div>\n      <div class=\"ct\">Ng\u01b0\u1eddi h\u1ecdc bi\u1ebft/l\u00e0m \u0111\u01b0\u1ee3c g\u00ec m\u1edbi?</div>\n      <div class=\"cd\">Quiz tr\u01b0\u1edbc-sau, skill demonstration. \u0110o gap gi\u1eefa pre v\u00e0 post. H\u1ea1n ch\u1ebf: bi\u1ebft trong l\u1edbp kh\u00f4ng c\u00f3 ngh\u0129a l\u00e0 l\u00e0m \u0111\u01b0\u1ee3c \u1edf c\u1eeda h\u00e0ng th\u1ef1c t\u1ebf</div>\n    </div>\n    <div class=\"card\" style=\"border-color:rgba(16,185,129,.3)\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">Level 3 \u00b7 Behavior \u2605</div>\n      <div class=\"ct\">H\u00e0nh vi c\u00f3 thay \u0111\u1ed5i trong c\u00f4ng vi\u1ec7c th\u1ef1c t\u1ebf?</div>\n      <div class=\"cd\">Observation 30\u201390 ng\u00e0y sau training. Manager checklist. Mystery shopper. \u0110\u00e2y l\u00e0 level quan tr\u1ecdng nh\u1ea5t \u2014 v\u00e0 \u00edt \u0111\u01b0\u1ee3c \u0111o nh\u1ea5t. C\u1ea7n manager involvement \u0111\u1ec3 \u0111o \u0111\u01b0\u1ee3c</div>\n    </div>\n    <div class=\"card\" style=\"border-color:rgba(16,185,129,.3)\">\n      <div class=\"cn\" style=\"color:var(--emerald)\">Level 4 \u00b7 Results \u2605</div>\n      <div class=\"ct\">KPI business c\u00f3 c\u1ea3i thi\u1ec7n?</div>\n      <div class=\"cd\">Customer satisfaction score, turnover rate, revenue, error rate. Kh\u00f3 nh\u1ea5t \u0111\u1ec3 isolate impact c\u1ee7a training. Nh\u01b0ng \u0111\u00e2y l\u00e0 ng\u00f4n ng\u1eef CEO mu\u1ed1n nghe</div>\n    </div>\n  </div>\n\n  <div class=\"hl\">\n    <div class=\"hl-label\">C\u00e1ch \u0111o Level 3 trong F&B chain \u2014 th\u1ef1c t\u1ebf</div>\n    <p style=\"margin-bottom:7px\">\u2460 Manager observation checklist: 5\u20137 h\u00e0nh vi c\u1ee5 th\u1ec3 c\u1ea7n quan s\u00e1t trong 30 ng\u00e0y sau training</p>\n    <p style=\"margin-bottom:7px\">\u2461 Mystery shopper: \u0111o tr\u1ef1c ti\u1ebfp h\u00e0nh vi d\u1ecbch v\u1ee5 \u1edf c\u1eeda h\u00e0ng \u2014 so s\u00e1nh tr\u01b0\u1edbc/sau training</p>\n    <p>\u2462 Peer observation: buddy system \u2014 nh\u00e2n vi\u00ean observe nhau v\u00e0 b\u00e1o c\u00e1o tu\u1ea7n 1 l\u1ea7n. Chi ph\u00ed th\u1ea5p nh\u1ea5t, c\u1ea7n setup c\u1ea9n th\u1eadn \u0111\u1ec3 kh\u00f4ng th\u00e0nh h\u00ecnh th\u1ee9c</p>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83d\udcca</div>\n      <div><div class=\"ex-label\">Thi\u1ebft k\u1ebf \u0111o l\u01b0\u1eddng</div><div class=\"ex-sub\">Ch\u1ecdn level \u0111o ph\u00f9 h\u1ee3p</div></div>\n    </div>\n    <div class=\"qq\">Sau training \"Customer complaint handling\" cho nh\u00e2n vi\u00ean ph\u1ee5c v\u1ee5, L&D mu\u1ed1n ch\u1ee9ng minh v\u1edbi CEO r\u1eb1ng training c\u00f3 ROI th\u1ef1c s\u1ef1. \u0110o l\u01b0\u1eddng n\u00e0o thuy\u1ebft ph\u1ee5c nh\u1ea5t?</div>\n    <div class=\"qopts\" id=\"q5opts\">\n      <button class=\"qopt\" onclick=\"AQ(5,this,'A')\"><span class=\"oletter\">A</span>Survey satisfaction ngay sau training \u2014 \u0111i\u1ec3m trung b\u00ecnh 4.5/5</button>\n      <button class=\"qopt\" onclick=\"AQ(5,this,'B')\"><span class=\"oletter\">B</span>Quiz ki\u1ec3m tra ki\u1ebfn th\u1ee9c tr\u01b0\u1edbc v\u00e0 sau training \u2014 \u0111i\u1ec3m t\u0103ng 40%</button>\n      <button class=\"qopt\" onclick=\"AQ(5,this,'C')\"><span class=\"oletter\">C</span>So s\u00e1nh t\u1ef7 l\u1ec7 complaint \u0111\u01b0\u1ee3c resolve t\u1ea1i c\u1eeda h\u00e0ng (kh\u00f4ng escalate) trong 30 ng\u00e0y tr\u01b0\u1edbc v\u00e0 sau training</button>\n      <button class=\"qopt\" onclick=\"AQ(5,this,'D')\"><span class=\"oletter\">D</span>\u0110\u1ebfm s\u1ed1 nh\u00e2n vi\u00ean \u0111\u00e3 tham gia \u0111\u1ee7 bu\u1ed5i training</button>\n    </div>\n    <div class=\"qfb\" id=\"qf5\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 5</div>\n    <div class=\"tw-text\">\"Survey sau training kh\u00f4ng \u0111o \u0111\u01b0\u1ee3c training c\u00f3 hi\u1ec7u qu\u1ea3 kh\u00f4ng \u2014 n\u00f3 ch\u1ec9 \u0111o training c\u00f3 \u0111\u01b0\u1ee3c th\u00edch kh\u00f4ng. Mu\u1ed1n b\u1ea3o v\u1ec7 ng\u00e2n s\u00e1ch L&D, ph\u1ea3i n\u00f3i \u0111\u01b0\u1ee3c ng\u00f4n ng\u1eef business: h\u00e0nh vi thay \u0111\u1ed5i, KPI c\u1ea3i thi\u1ec7n.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(4)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n5\" onclick=\"go(6)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h5\">Tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550 M6 \u2014 Calendar & Budget \u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m6\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">L&D Th\u1ef1c Chi\u1ebfn \u2605 \u00b7 B\u00e0i cu\u1ed1i \u00b7 Phase 1 Complete</div>\n      <div class=\"hero-num\">B\u00e0i 6 / 6</div>\n      <div class=\"hero-title\">Training calendar & budget cho chu\u1ed7i 50+ c\u1eeda h\u00e0ng</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"M\u1ed7i n\u0103m L&D team c\u1ee7a Hi\u1ec1n ph\u1ea3i submit training plan v\u00e0 budget cho n\u0103m t\u1edbi. N\u0103m \u0111\u1ea7u ti\u00ean Hi\u1ec1n l\u00e0m \u1edf Golden Gate, team submit 1 trang gi\u1ea5y v\u1edbi 3 ch\u01b0\u01a1ng tr\u00ecnh, kh\u00f4ng c\u00f3 ROI projection. CFO h\u1ecfi: 'T\u1ea1i sao c\u1ea7n 2 t\u1ef7? Impact l\u00e0 g\u00ec?' Team kh\u00f4ng tr\u1ea3 l\u1eddi \u0111\u01b0\u1ee3c. N\u0103m \u0111\u00f3 budget b\u1ecb c\u1eaft 40%. N\u0103m sau Hi\u1ec1n h\u01b0\u1edbng d\u1eabn team submit 12 trang v\u1edbi business case \u0111\u1ea7y \u0111\u1ee7 cho m\u1ed7i ch\u01b0\u01a1ng tr\u00ecnh. Budget \u0111\u01b0\u1ee3c approve 100% v\u00e0 t\u0103ng 20%.\"</div>\n\n  <p class=\"body\">Training calendar kh\u00f4ng ch\u1ec9 l\u00e0 l\u1ecbch \u2014 \u0111\u00f3 l\u00e0 <b>k\u1ebf ho\u1ea1ch \u0111\u1ea7u t\u01b0 c\u00f3 business case r\u00f5 r\u00e0ng</b>. V\u00e0 budget L&D kh\u00f4ng ph\u1ea3i \"chi ph\u00ed\" \u2014 \u0111\u00f3 l\u00e0 \u0111\u1ea7u t\u01b0 c\u00f3 ROI c\u1ea7n \u0111\u01b0\u1ee3c ch\u1ee9ng minh b\u1eb1ng data.</p>\n\n  <div class=\"sec-title\">Nguy\u00ean t\u1eafc l\u00ean training calendar cho chu\u1ed7i</div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">Nguy\u00ean t\u1eafc 1 \u00b7 Align v\u1edbi business cycle</div>\n    <div class=\"ct\">Training ph\u1ea3i \"tr\u00e1nh m\u00f9a cao \u0111i\u1ec3m\" v\u00e0 \"chu\u1ea9n b\u1ecb cho m\u00f9a cao \u0111i\u1ec3m\"</div>\n    <div class=\"cd\" style=\"margin-top:5px\">F&B chain th\u01b0\u1eddng c\u00f3 peak Q4 (cu\u1ed1i n\u0103m) v\u00e0 Q1 (T\u1ebft). Training core skills n\u00ean \u0111\u01b0\u1ee3c done tr\u01b0\u1edbc Q4 \u00edt nh\u1ea5t 6 tu\u1ea7n \u2014 \u0111\u1ec3 c\u00f3 th\u1eddi gian practice v\u00e0 behavioral change x\u1ea3y ra tr\u01b0\u1edbc khi b\u1eadn nh\u1ea5t.</div>\n  </div>\n  <div class=\"card-full\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">Nguy\u00ean t\u1eafc 2 \u00b7 Mandatory vs optional</div>\n    <div class=\"ct\">Ph\u00e2n lo\u1ea1i r\u00f5 \u2014 kh\u00f4ng ph\u1ea3i m\u1ecdi training \u0111\u1ec1u b\u1eaft bu\u1ed9c t\u1ea5t c\u1ea3</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Mandatory (to\u00e0n b\u1ed9): An to\u00e0n th\u1ef1c ph\u1ea9m, Fire safety, Quy tr\u00ecnh core, Onboarding. Role-specific: Training theo v\u1ecb tr\u00ed v\u00e0 level. Optional/development: Ng\u01b0\u1eddi mu\u1ed1n ph\u00e1t tri\u1ec3n c\u00f3 th\u1ec3 \u0111\u0103ng k\u00fd th\u00eam.</div>\n  </div>\n  <div class=\"card-full\" style=\"margin-bottom:18px\">\n    <div class=\"cn\" style=\"color:var(--emerald)\">Nguy\u00ean t\u1eafc 3 \u00b7 Budget ph\u00e2n b\u1ed5 theo ROI ti\u1ec1m n\u0103ng</div>\n    <div class=\"ct\">Kh\u00f4ng chia \u0111\u1ec1u \u2014 \u01b0u ti\u00ean training c\u00f3 impact cao nh\u1ea5t</div>\n    <div class=\"cd\" style=\"margin-top:5px\">Ph\u00e2n t\u00edch: training n\u00e0o li\u00ean quan tr\u1ef1c ti\u1ebfp \u0111\u1ebfn revenue v\u00e0 customer satisfaction \u2192 \u0111\u1ea7u t\u01b0 nhi\u1ec1u h\u01a1n. Training compliance/safety \u2192 c\u1ea7n nh\u01b0ng t\u1ed1i \u01b0u chi ph\u00ed. Training \"nice to have\" \u2192 c\u1eaft khi ng\u00e2n s\u00e1ch tight.</div>\n  </div>\n\n  <div class=\"ins\">\n    <div class=\"ins-label\">Business case \u0111\u01a1n gi\u1ea3n cho m\u1ed7i training \u2014 3 con s\u1ed1 c\u1ea7n c\u00f3</div>\n    <p style=\"margin-bottom:5px\"><b style=\"color:var(--gold)\">\u2460 Chi ph\u00ed:</b> Trainer fee + materials + venue + opportunity cost (nh\u00e2n vi\u00ean kh\u00f4ng b\u00e1n h\u00e0ng trong th\u1eddi gian training)</p>\n    <p style=\"margin-bottom:5px\"><b style=\"color:var(--gold)\">\u2461 Impact d\u1ef1 ki\u1ebfn:</b> N\u1ebfu h\u00e0nh vi X thay \u0111\u1ed5i \u2192 KPI Y c\u1ea3i thi\u1ec7n bao nhi\u00eau % \u2192 doanh thu/chi ph\u00ed t\u0103ng/gi\u1ea3m bao nhi\u00eau?</p>\n    <p><b style=\"color:var(--gold)\">\u2462 ROI:</b> (Impact - Cost) / Cost \u00d7 100%. N\u1ebfu kh\u00f4ng t\u00ednh \u0111\u01b0\u1ee3c \u2014 t\u1ed1i thi\u1ec3u ph\u1ea3i \u0111\u1ecbnh ngh\u0129a \u0111\u01b0\u1ee3c \"th\u00e0nh c\u00f4ng tr\u00f4ng nh\u01b0 th\u1ebf n\u00e0o sau 3 th\u00e1ng\"</p>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\u2705</div>\n      <div><div class=\"ex-label\">Cam k\u1ebft L&D th\u1ef1c chi\u1ebfn</div><div class=\"ex-sub\">Ch\u1ecdn \u00edt nh\u1ea5t 3 \u0111\u1ec3 ho\u00e0n th\u00e0nh kh\u00f3a h\u1ecdc</div></div>\n    </div>\n    <div id=\"cl6\">\n      <div class=\"chi\" onclick=\"TC6(this)\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">L\u1ea7n training ti\u1ebfp theo \u2014 x\u00e1c \u0111\u1ecbnh behavioral outcome c\u1ee5 th\u1ec3 TR\u01af\u1edaC khi thi\u1ebft k\u1ebf n\u1ed9i dung<small>Vi\u1ebft ra: \"Sau training, ng\u01b0\u1eddi h\u1ecdc s\u1ebd l\u00e0m \u0111\u01b0\u1ee3c X trong Y% tr\u01b0\u1eddng h\u1ee3p\"</small></div></div>\n      <div class=\"chi\" onclick=\"TC6(this)\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">Th\u00eam \u00edt nh\u1ea5t 1 ho\u1ea1t \u0111\u1ed9ng t\u01b0\u01a1ng t\u00e1c v\u00e0o training ti\u1ebfp theo \u2014 kh\u00f4ng ch\u1ec9 slide<small>Think-pair-share, role-play, case study th\u1ef1c t\u1ebf, ho\u1eb7c quiz c\u00f3 discussion</small></div></div>\n      <div class=\"chi\" onclick=\"TC6(this)\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">\u0110o Kirkpatrick Level 3 cho \u00edt nh\u1ea5t 1 ch\u01b0\u01a1ng tr\u00ecnh training \u0111ang c\u00f3<small>T\u1ea1o observation checklist cho manager \u2014 5 h\u00e0nh vi c\u1ea7n quan s\u00e1t trong 30 ng\u00e0y sau training</small></div></div>\n      <div class=\"chi\" onclick=\"TC6(this)\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">T\u1ea1o business case 1 trang cho training budget n\u0103m t\u1edbi \u2014 k\u00e8m ROI projection<small>Kh\u00f4ng ph\u1ea3i \"ch\u00fang t\u00f4i c\u1ea7n 500 tri\u1ec7u\" m\u00e0 l\u00e0 \"500 tri\u1ec7u \u2192 gi\u1ea3m turnover 15% \u2192 ti\u1ebft ki\u1ec7m 2 t\u1ef7 chi ph\u00ed tuy\u1ec3n\"</small></div></div>\n      <div class=\"chi\" onclick=\"TC6(this)\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">Th\u1eed \u00e1p d\u1ee5ng blended learning cho 1 ch\u01b0\u01a1ng tr\u00ecnh: pre-work e-learning + ILT + microlearning sau<small>\u0110o xem behavior retention sau 30 ng\u00e0y c\u00f3 t\u1ed1t h\u01a1n ILT \u0111\u01a1n thu\u1ea7n kh\u00f4ng</small></div></div>\n    </div>\n    <div class=\"qfb\" id=\"cf6\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 To\u00e0n kh\u00f3a K6 & Phase 1</div>\n    <div class=\"tw-text\">\"L&D kh\u00f4ng ph\u1ea3i t\u1ed5 ch\u1ee9c s\u1ef1 ki\u1ec7n training \u2014 L&D l\u00e0 \u0111\u1ea7u t\u01b0 v\u00e0o n\u0103ng l\u1ef1c con ng\u01b0\u1eddi. Mu\u1ed1n \u0111\u01b0\u1ee3c \u0111\u1ea7u t\u01b0 \u0111\u00fang m\u1ee9c, L&D ph\u1ea3i bi\u1ebft \u0111o ROI b\u1eb1ng ng\u00f4n ng\u1eef m\u00e0 CEO v\u00e0 CFO hi\u1ec3u.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group \u00b7 PeopleOS Community 2026</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(5)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n6\" onclick=\"done()\" disabled>Ho\u00e0n th\u00e0nh Phase 1 \ud83c\udf89</button>\n  </div>\n  <div class=\"ulock\" id=\"h6\">Ch\u1ecdn \u00edt nh\u1ea5t 3 cam k\u1ebft \u0111\u1ec3 ho\u00e0n th\u00e0nh</div>\n</div>\n\n<!-- COMPLETE -->\n<div class=\"cscreen\" id=\"complete\">\n  <div class=\"cico\">\ud83c\udfc5</div>\n  <div class=\"ctitle\">Phase 1 Ho\u00e0n Th\u00e0nh!</div>\n  <div class=\"csub\">B\u1ea1n \u0111\u00e3 ho\u00e0n th\u00e0nh to\u00e0n b\u1ed9 <b>6 kh\u00f3a h\u1ecdc C\u1ea5p 1 \u2014 HR Staff & Specialist</b>.<br>T\u1ed5ng c\u1ed9ng: 36 b\u00e0i h\u1ecdc \u00b7 696 XP \u00b7 S\u1eb5n s\u00e0ng cho C\u1ea5p 2.</div>\n  <div class=\"phase-banner\">\n    <div class=\"phase-banner-title\">\ud83d\ude80 Ch\u1eb7ng 1 \u00b7 HR Foundation \u2014 HO\u00c0N TH\u00c0NH</div>\n    <div class=\"phase-banner-sub\">EQ & Self-Mastery \u00b7 Giao ti\u1ebfp & \u1ea2nh h\u01b0\u1edfng \u00b7 AI Literacy<br>HR Ops \u00b7 Recruiting \u00b7 L&D Th\u1ef1c Chi\u1ebfn</div>\n  </div>\n  <div class=\"certcard\">\n    <div class=\"cert-lbl\">Ch\u1ee9ng ch\u1ec9 ho\u00e0n th\u00e0nh \u00b7 PeopleOS</div>\n    <div class=\"cert-name\">L&D Th\u1ef1c Chi\u1ebfn</div>\n    <div class=\"cert-course\">C\u1ea5p 1 \u2014 HR Staff & Specialist \u00b7 6 modules \u00b7 ~20 ph\u00fat</div>\n    <div class=\"cert-sig\">TaHien \u2014 CHCO Golden Gate Group \u2014 bi\u00ean so\u1ea1n cho c\u1ed9ng \u0111\u1ed3ng HR Vietnam.<br>PeopleOS Community \u00b7 2026</div>\n  </div>\n  <button class=\"btncert\" onclick=\"alert('T\u00ednh n\u0103ng xu\u1ea5t PDF s\u1ebd c\u00f3 trong phi\u00ean b\u1ea3n \u0111\u1ea7y \u0111\u1ee7!')\">T\u1ea3i ch\u1ee9ng ch\u1ec9 PDF</button>\n  <button class=\"btnnext2\" onclick=\"window.location.href='/'\">\u2190 V\u1ec1 Hub \u00b7 B\u1eaft \u0111\u1ea7u C\u1ea5p 2</button>\n</div>\n</div>\n\n<script>\nvar cur=1,tot=6,dm={};\nfunction buildDots(){\n  var c=document.getElementById('dots');c.innerHTML='';\n  for(var i=1;i<=tot;i++){\n    var d=document.createElement('div');\n    d.className='dot'+(i===cur?' active':(dm[i]?' done':''));\n    (function(n){d.onclick=function(){if(n<=cur||dm[n-1])go(n);};})(i);\n    c.appendChild(d);\n  }\n}\nfunction updP(){\n  var p=Math.round(((cur-1)/tot)*100);\n  document.getElementById('pfill').style.width=p+'%';\n  document.getElementById('ppct').textContent=p+'%';\n  document.getElementById('plabel').textContent='B\u00e0i '+cur+' / '+tot;\n}\nfunction go(n){\n  document.getElementById('m'+cur).classList.remove('active');\n  dm[cur]=true;cur=n;\n  var el=document.getElementById('m'+cur);\n  if(el)el.classList.add('active');\n  buildDots();updP();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction unlock(b,h){\n  var bn=document.getElementById(b);if(bn)bn.disabled=false;\n  var hn=document.getElementById(h);if(hn)hn.style.display='none';\n}\n\n/* M1 TNA matrix */\nfunction pickTNA(opt){\n  ['A','B','C','D'].forEach(function(o){\n    var el=document.getElementById('tna-'+o);\n    el.classList.remove('selected','correct','incorrect');\n    el.onclick=null;\n  });\n  var fb=document.getElementById('qf1');\n  var el=document.getElementById('tna-'+opt);\n  if(opt==='B'){\n    el.classList.add('correct');\n    fb.className='qfb show correct';\n    fb.textContent='\u0110\u00fang! Supervisor n\u00f3i \"bi\u1ebft quy t\u1eafc nh\u01b0ng kh\u00f4ng \u0111\u1ec3 \u00fd\" = v\u1ea5n \u0111\u1ec1 thi\u1ebfu \u0111\u1ed9ng l\u1ef1c v\u00e0 accountability, kh\u00f4ng ph\u1ea3i thi\u1ebfu ki\u1ebfn th\u1ee9c. Gi\u1ea3i ph\u00e1p: consequence r\u00f5 r\u00e0ng (nh\u1eafc nh\u1edf, review), feedback loop, v\u00e0 c\u00f3 th\u1ec3 incentive cho compliance. Training th\u00eam s\u1ebd kh\u00f4ng gi\u1ea3i quy\u1ebft \u0111\u01b0\u1ee3c v\u1ea5n \u0111\u1ec1 n\u00e0y.';\n  } else {\n    el.classList.add('incorrect');\n    document.getElementById('tna-B').classList.add('correct');\n    fb.className='qfb show wrong';\n    if(opt==='A')fb.textContent='Ch\u01b0a \u0111\u00fang. H\u1ecd \u0111\u00e3 \u0111\u01b0\u1ee3c training v\u00e0 bi\u1ebft quy t\u1eafc r\u1ed3i. Training th\u00eam s\u1ebd kh\u00f4ng thay \u0111\u1ed5i \u0111\u01b0\u1ee3c khi v\u1ea5n \u0111\u1ec1 l\u00e0 thi\u1ebfu \u0111\u1ed9ng l\u1ef1c/accountability.';\n    else if(opt==='C')fb.textContent='Ch\u01b0a \u0111\u00fang. Kh\u00f4ng c\u00f3 d\u1ea5u hi\u1ec7u quy tr\u00ecnh hay m\u00f4i tr\u01b0\u1eddng c\u1ea3n tr\u1edf h\u1ecd. Supervisor n\u00f3i h\u1ecd \"kh\u00f4ng \u0111\u1ec3 \u00fd\" \u2014 v\u1ea5n \u0111\u1ec1 l\u00e0 attitude v\u00e0 accountability.';\n    else fb.textContent='Ch\u01b0a \u0111\u00fang. \u0110\u00e2y ch\u1ee7 y\u1ebfu l\u00e0 v\u1ea5n \u0111\u1ec1 \u0111\u1ed9ng l\u1ef1c \u2014 kh\u00f4ng c\u1ea7n c\u1ea3 training l\u1eabn fix h\u1ec7 th\u1ed1ng. C\u1ea7n t\u1eadp trung v\u00e0o consequence v\u00e0 accountability tr\u01b0\u1edbc.';\n  }\n  unlock('n1','h1');\n}\n\n/* M2, M3, M5 quiz */\nfunction AQ(m,el,ans){\n  var correct={2:'B',3:'B',5:'C'};\n  document.querySelectorAll('#q'+m+'opts .qopt').forEach(function(o){o.disabled=true;});\n  var fb=document.getElementById('qf'+m);\n  if(ans===correct[m]){\n    el.classList.add('correct');fb.className='qfb show correct';\n    if(m===2)fb.textContent='\u0110\u00fang! B\u1ecf qua b\u01b0\u1edbc Analyze l\u00e0 l\u1ed7i ph\u1ed5 bi\u1ebfn nh\u1ea5t. Kh\u00f4ng bi\u1ebft gap c\u1ee5 th\u1ec3 l\u00e0 g\u00ec, kh\u00f4ng bi\u1ebft behavioral outcome mong mu\u1ed1n, kh\u00f4ng bi\u1ebft training c\u00f3 ph\u1ea3i gi\u1ea3i ph\u00e1p \u0111\u00fang \u2192 thi\u1ebft k\u1ebf n\u1ed9i dung xong m\u1edbi h\u1ecfi \"\u0111o g\u00ec\" \u2192 kh\u00f4ng \u0111o \u0111\u01b0\u1ee3c \u2192 kh\u00f4ng ch\u1ee9ng minh \u0111\u01b0\u1ee3c ROI.';\n    if(m===3)fb.textContent='\u0110\u00fang! C\u00e2u B m\u1eddi ng\u01b0\u1eddi ph\u1ea3n \u0111\u1ed1i chia s\u1ebb c\u1ee5 th\u1ec3 \u2014 t\u1ea1o opportunity \u0111\u1ec3 gi\u1ea3i quy\u1ebft objection th\u1eadt s\u1ef1 ngay tr\u01b0\u1edbc c\u1ea3 l\u1edbp. Nh\u1eefng ng\u01b0\u1eddi kh\u00e1c trong ph\u00f2ng c\u0169ng \u0111ang ngh\u0129 nh\u01b0 v\u1eady \u2014 gi\u1ea3i quy\u1ebft \u0111\u01b0\u1ee3c cho anh \u1ea5y = gi\u1ea3i quy\u1ebft \u0111\u01b0\u1ee3c cho c\u1ea3 ph\u00f2ng.';\n    if(m===5)fb.textContent='\u0110\u00fang! \u0110\u00e2y l\u00e0 Level 3 (Behavior) v\u00e0 g\u1ea7n Level 4 (Results). So s\u00e1nh \"resolve t\u1ea1i ch\u1ed7\" tr\u01b0\u1edbc/sau = \u0111o h\u00e0nh vi th\u1eadt trong c\u00f4ng vi\u1ec7c th\u1ef1c t\u1ebf, kh\u00f4ng ph\u1ea3i trong l\u1edbp. \u0110\u00e2y l\u00e0 con s\u1ed1 CEO v\u00e0 CFO mu\u1ed1n th\u1ea5y.';\n    unlock('n'+m,'h'+m);\n  } else {\n    el.classList.add('wrong');\n    var ci={2:1,3:1,5:2}[m];\n    document.querySelectorAll('#q'+m+'opts .qopt')[ci].classList.add('correct');\n    fb.className='qfb show wrong';\n    if(m===2)fb.textContent='Ch\u01b0a \u0111\u00fang. T\u1ea5t c\u1ea3 c\u00e1c b\u01b0\u1edbc Develop (A), Implement (C), Evaluate (D) \u0111\u1ec1u quan tr\u1ecdng \u2014 nh\u01b0ng Analyze (B) l\u00e0 b\u01b0\u1edbc n\u1ec1n t\u1ea3ng nh\u1ea5t. Kh\u00f4ng c\u00f3 Analyze t\u1ed1t \u2192 Design sai \u2192 m\u1ecdi th\u1ee9 sau \u0111\u00f3 sai theo.';\n    if(m===3)fb.textContent='Ch\u01b0a \u0111\u00fang. (A) tranh lu\u1eadn tr\u1ef1c ti\u1ebfp s\u1ebd t\u1ea1o th\u1ebf \u0111\u1ed1i \u0111\u1ea7u. (C) b\u1ecf qua = m\u1ea5t c\u1ea3 ph\u00f2ng. (D) postpone = kh\u00f4ng gi\u1ea3i quy\u1ebft. C\u00e2u B chuy\u1ec3n ng\u01b0\u1eddi ph\u1ea3n \u0111\u1ed1i th\u00e0nh ng\u01b0\u1eddi \u0111\u1ed3ng h\u00e0nh gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1.';\n    if(m===5)fb.textContent='Ch\u01b0a \u0111\u00fang. (A) Level 1 \u2014 satisfaction, kh\u00f4ng \u0111o \u0111\u01b0\u1ee3c learning. (B) Level 2 \u2014 learning trong l\u1edbp, kh\u00f4ng bi\u1ebft c\u00f3 \u00e1p d\u1ee5ng kh\u00f4ng. (D) ch\u1ec9 l\u00e0 attendance metric. C\u00e2u C \u0111o \u0111\u01b0\u1ee3c behavior thay \u0111\u1ed5i trong th\u1ef1c t\u1ebf \u2014 \u0111\u00e2y m\u1edbi l\u00e0 ROI th\u1eadt.';\n    setTimeout(function(){unlock('n'+m,'h'+m);},1600);\n  }\n}\n\n/* M4 format picker */\nfunction pickFmt(el,type){\n  document.querySelectorAll('#fmt4 .fmt-card').forEach(function(c){c.disabled=true;});\n  var fb=document.getElementById('qf4');\n  if(type==='good'){\n    el.classList.add('sel-good');fb.className='qfb show correct';\n    fb.textContent='\u0110\u00fang! E-learning + video demo l\u00e0 ph\u00f9 h\u1ee3p nh\u1ea5t cho t\u00ecnh hu\u1ed1ng n\u00e0y: c\u1ea7n reach 500 ng\u01b0\u1eddi tr\u00ean 50 c\u1eeda h\u00e0ng v\u1edbi n\u1ed9i dung chu\u1ea9n h\u00f3a, kh\u00f4ng c\u00f3 ng\u00e2n s\u00e1ch trainer \u0111i t\u1eebng c\u1eeda h\u00e0ng. N\u1ed9i dung l\u00e0 procedural (quy tr\u00ecnh) \u2014 ph\u00f9 h\u1ee3p v\u1edbi e-learning. Clip demo tr\u1ef1c quan h\u01a1n text.';\n    unlock('n4','h4');\n  } else {\n    el.classList.add('sel-bad');\n    document.querySelectorAll('#fmt4 .fmt-card')[1].classList.add('sel-good');\n    fb.className='qfb show wrong';\n    if(el.querySelector('.fmt-title').textContent.includes('ILT'))fb.textContent='Ch\u01b0a \u0111\u00fang. ILT t\u1eadp trung 500 ng\u01b0\u1eddi t\u1eeb 50 c\u1eeda h\u00e0ng v\u1ec1 1 n\u01a1i l\u00e0 logistically kh\u00f4ng kh\u1ea3 thi v\u00e0 t\u1ed1n k\u00e9m. Ph\u00f9 h\u1ee3p nh\u1ea5t khi c\u1ea7n th\u1ea3o lu\u1eadn v\u00e0 practice \u2014 kh\u00f4ng ph\u1ea3i khi c\u1ea7n truy\u1ec1n quy tr\u00ecnh chu\u1ea9n h\u00f3a.';\n    else if(el.querySelector('.fmt-title').textContent.includes('Micro'))fb.textContent='Ch\u01b0a \u0111\u00fang. Microlearning t\u1ed1t \u0111\u1ec3 reinforce sau khi \u0111\u00e3 h\u1ecdc n\u1ed9i dung ch\u00ednh \u2014 kh\u00f4ng ph\u1ea3i \u0111\u1ec3 h\u1ecdc quy tr\u00ecnh m\u1edbi t\u1eeb \u0111\u1ea7u. 500 ng\u01b0\u1eddi c\u1ea7n n\u1eafm \u0111\u1ee7 tr\u01b0\u1edbc khi \u00e1p d\u1ee5ng, kh\u00f4ng ph\u1ea3i nh\u1eadn tips r\u1ea3i r\u00e1c.';\n    else fb.textContent='Ch\u01b0a \u0111\u00fang. OJT v\u1edbi buddy t\u1ed1t cho k\u1ef9 n\u0103ng tay ch\u00e2n \u2014 nh\u01b0ng nguy c\u01a1 buddy truy\u1ec1n sai c\u00e1ch n\u1ebfu ch\u01b0a \u0111\u01b0\u1ee3c train \u0111\u00fang. V\u00e0 v\u1edbi 50 c\u1eeda h\u00e0ng, kh\u00f4ng ki\u1ec3m so\u00e1t \u0111\u01b0\u1ee3c ch\u1ea5t l\u01b0\u1ee3ng nh\u1ea5t qu\u00e1n.';\n    setTimeout(function(){unlock('n4','h4');},1600);\n  }\n}\n\n/* M6 checklist */\nvar cc6=0;\nfunction TC6(el){\n  var box=el.querySelector('.chbox');\n  var on=el.getAttribute('data-on')==='true';\n  if(!on){box.classList.add('on');el.setAttribute('data-on','true');cc6++;}\n  else{box.classList.remove('on');el.setAttribute('data-on','false');cc6--;}\n  var fb=document.getElementById('cf6');\n  if(cc6>=3){\n    fb.className='qfb show correct';\n    fb.textContent='Xu\u1ea5t s\u1eafc! '+cc6+' cam k\u1ebft cho L&D th\u1ef1c chi\u1ebfn. B\u1ea1n v\u1eeba ho\u00e0n th\u00e0nh Phase 1 \u2014 HR Foundation. S\u1eb5n s\u00e0ng cho C\u1ea5p 2: HR Manager & Senior Specialist!';\n    unlock('n6','h6');\n  } else {fb.className='';}\n}\n\nfunction done(){\n  document.getElementById('m6').style.display='none';\n  document.getElementById('complete').classList.add('show');\n  dm[6]=true;cur=7;\n  document.getElementById('pfill').style.width='100%';\n  document.getElementById('ppct').textContent='100%';\n  document.getElementById('plabel').textContent='Ho\u00e0n th\u00e0nh Phase 1!';\n  buildDots();window.scrollTo({top:0,behavior:'smooth'});\n  localStorage.setItem('peopleos_k6_done','true');\n  localStorage.setItem('peopleos_phase1_done','true');\n}\nbuildDots();updP();\n</script>\n</body>\n</html>\n");
  return { props: {} };
}
